import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { Workspace, Scenario, IntegrationStatus } from "../../src/shared/workspace";
import type { EligibilityAssessment, RecallMatchStatus, ValidationReason } from "../../src/domain/types";
import { EvidenceCitation, EvidenceProvider, EvidenceRef, safeHttpUrl } from "./Evidence";
import { WhatIfPanel } from "./WhatIfPanel";
import { InvestigationGlance, ToolTimeline } from "./Glance";
import { boundPartialEvidence, investigationHeading, isPartialInvestigation, presentLotScope, isInventoryUnassessed } from "./partial-investigation";

type View = "recall" | "exposure" | "plan" | "actions";
type Tone = "neutral" | "green" | "red" | "yellow";
type Progress = Pick<Workspace, "revision" | "incidentId" | "agentRun"> & {integrations: Pick<Workspace["integrations"], "meterless">};
const views: Array<{ id: View; label: string; number: string; title: string; subtitle: string }> = [
  { id: "recall", label: "Recall", number: "01", title: "Understand the recall", subtitle: "Source evidence, exact scope and required follow-up." },
  { id: "exposure", label: "Exposure", number: "02", title: "Locate the exposure", subtitle: "Recall matching and local release are separate checks." },
  { id: "plan", label: "Response plan", number: "03", title: "Keep the supply covered", subtitle: "A calculated transfer plan that still meets every site's demand, reserve and deadline." },
  { id: "actions", label: "Actions", number: "04", title: "Approve and verify", subtitle: "Sandbox writes, receipts and the incident audit." },
];
const scenarioLabels: Record<Scenario, string> = {
  on_time: "Supplier on time",
  supplier_late: "Supplier delayed",
  qa_missing: "Delayed + QA missing",
};

function Badge({ children, tone = "neutral" }: { children: React.ReactNode; tone?: Tone }) {
  return <span className={`badge badge-${tone}`}>{children}</span>;
}
function Clock({ value, date = false }: { value: string; date?: boolean }) {
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return <span className="mono">{value || "—"}</span>;
  return <time className="mono" dateTime={value}>{new Intl.DateTimeFormat("en-GB", date ? { day: "2-digit", month: "short", year: "numeric", timeZone: "UTC" } : { hour: "2-digit", minute: "2-digit", timeZone: "UTC", hour12: false }).format(parsed)}{date ? "" : " UTC"}</time>;
}
function Reasons({ reasons }: { reasons: ValidationReason[] }) {
  return reasons.length ? <ul className="reason-list">{reasons.map((reason, i) => <li key={`${reason.code}-${i}`}><span>{reason.message}</span><div className="reason-evidence"><code>{reason.code}</code>{reason.entityId && <EvidenceRef id={reason.entityId} />}{reason.evidenceRefs.map((ref) => <EvidenceRef key={ref} id={ref} />)}</div></li>)}</ul> : <p className="quiet">No additional validation messages.</p>;
}
function MatchBadge({ status }: { status: RecallMatchStatus }) {
  const label = { CONFIRMED_MATCH: "Confirmed match", POSSIBLE_MATCH_REVIEW: "Needs review", NOT_LISTED_IN_THIS_RECALL: "Not listed in this recall", OUT_OF_PRODUCT_SCOPE: "Outside product scope" }[status];
  return <Badge tone={status === "CONFIRMED_MATCH" ? "red" : status === "POSSIBLE_MATCH_REVIEW" ? "yellow" : "neutral"}>{label}</Badge>;
}
function Availability({ assessment }: { assessment?: EligibilityAssessment }) {
  if (!assessment) return <Badge tone="yellow">Unassessed</Badge>;
  return <Badge tone={assessment.status === "ELIGIBLE" ? "green" : assessment.status === "CONDITIONAL_PROJECTED" ? "yellow" : "neutral"}>{assessment.status === "ELIGIBLE" ? `${assessment.eligibleEa} EA eligible` : assessment.status === "CONDITIONAL_PROJECTED" ? `${assessment.eligibleEa} EA conditional` : "Excluded"}</Badge>;
}

export default function App() {
  const [workspace, setWorkspace] = useState<Workspace | null>(null);
  const [view, setView] = useState<View>("recall");
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [agentMessage, setAgentMessage] = useState("");
  const busyRef = useRef<string | null>(null);
  const runStatusRef = useRef<Workspace["agentRun"]["status"] | undefined>(undefined);
  const selected = views.find((item) => item.id === view)!;

  const refresh = useCallback(async (signal?: AbortSignal) => {
    const response = await fetch("/api/workspace", { signal, headers: { Accept: "application/json" } });
    const data = await response.json() as Workspace | { error: string };
    if (!response.ok || "error" in data) throw new Error("error" in data ? data.error : `Workspace could not load (${response.status}).`);
    setWorkspace(data);
    return data;
  }, []);

  useEffect(() => {
    const controller = new AbortController();
    refresh(controller.signal).catch((cause: unknown) => {
      if (!controller.signal.aborted) setError(cause instanceof Error ? cause.message : "Workspace could not load.");
    }).finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [refresh]);

  useEffect(() => {
    runStatusRef.current = workspace?.agentRun.status;
  }, [workspace?.agentRun.status]);

  useEffect(() => {
    const incidentId = workspace?.incidentId;
    const runId = workspace?.agentRun.runId;
    if (!incidentId || !runId || runStatusRef.current !== "running") return;
    const controller = new AbortController();
    let stopped = false; let finished = false; let timer: number | undefined;
    const poll = async () => {
      // A mutation already returns a fresh workspace. Do not overlap its source read.
      if (runStatusRef.current !== "running") return;
      try {
        if (busyRef.current) return;
        const response = await fetch("/api/progress", {signal: controller.signal, headers: {Accept: "application/json"}});
        const progress = await response.json() as Progress | {error: string};
        if (!response.ok || "error" in progress) throw new Error("error" in progress ? progress.error : `Progress could not load (${response.status}).`);
        if (stopped || busyRef.current) return;
        const sameRun = progress.incidentId === incidentId && progress.agentRun.runId === runId;
        const terminal = !sameRun || progress.agentRun.status !== "running";
        if (terminal) {finished = true; busyRef.current = "/api/workspace"; setBusy("/api/workspace");}
        if (sameRun) setWorkspace(current => current?.incidentId === incidentId && current.agentRun.runId === runId && progress.revision >= current.revision
          ? {...current, revision: progress.revision, agentRun: progress.agentRun, integrations: {...current.integrations, meterless: progress.integrations.meterless}}
          : current);
        if (terminal) {
          try {await refresh(controller.signal);}
          catch (cause) {if (!controller.signal.aborted) setError(cause instanceof Error ? `Investigation finished, but current sources could not refresh: ${cause.message}` : "Investigation finished, but current sources could not refresh.");}
          finally {if (busyRef.current === "/api/workspace") {busyRef.current = null; setBusy(null);}}
        }
      } catch (cause) {
        if (!controller.signal.aborted) setError(cause instanceof Error ? cause.message : "Agent progress could not refresh.");
      } finally {
        // Chained after the awaited request: at most one poll/terminal refresh is in flight.
        if (!stopped && !finished) timer = window.setTimeout(() => void poll(), 2000);
      }
    };
    timer = window.setTimeout(() => void poll(), 2000);
    return () => {stopped = true; controller.abort(); if (timer !== undefined) window.clearTimeout(timer);};
    // Run identity owns this lifecycle. A terminal status merge must not abort its one final refresh.
  }, [workspace?.incidentId, workspace?.agentRun.runId, refresh]);

  const mutate = async (path: string, payload: unknown, success: string) => {
    if (busyRef.current) return;
    busyRef.current = path;
    setBusy(path); setError(null); setNotice(null);
    try {
      const response = await fetch(path, { method: "POST", headers: { "Content-Type": "application/json", Accept: "application/json" }, body: JSON.stringify(payload) });
      const data = await response.json() as Workspace | { error: string };
      if (!response.ok || "error" in data) throw new Error("error" in data ? data.error : `The request failed (${response.status}).`);
      setWorkspace(data); setNotice(success);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "The request failed.");
      try { await refresh(); } catch { /* Keep the original mutation error visible. */ }
    } finally { busyRef.current = null; setBusy(null); }
  };

  const inventoryAssessments = useMemo(() => new Map(workspace?.assessment.inventory.map((item) => [item.entityId, item]) ?? []), [workspace?.assessment]);
  const confirmedIds = workspace?.assessment.inventory.filter((item) => item.recallMatch.status === "CONFIRMED_MATCH").map((item) => item.entityId) ?? [];
  const holdPending = workspace?.snapshot.inventory.some((item) => confirmedIds.includes(item.id) && !item.allocationHold) ?? false;
  const plan = workspace?.plan;
  const feasible = plan?.status === "feasible" ? plan : null;
  const planCurrent = workspace?.planState === "current" && feasible?.inputFingerprint === workspace?.assessment.inputFingerprint;
  const busyOrRunning = !!busy || workspace?.agentRun.status === "running";
  const incidentReserved = workspace?.planState === "reserved";
  const claimsCurrent = workspace?.agentRun.claimAudit?.status === "verified" && workspace.agentRun.claimAudit.result.checked?.snapshotHash === workspace.assessment.inputFingerprint;
  const investigationNeedsEvidence = workspace?.agentRun.investigation?.disposition === "needs_evidence";
  const agentBadge = workspace?.agentRun.status === "blocked" && investigationNeedsEvidence ? "Operator evidence needed"
    : workspace?.agentRun.status === "complete" ? workspace.agentRun.claimAudit?.status === "verified" ? claimsCurrent ? "Claims checked" : "Claims checked · older snapshot"
      : workspace.agentRun.investigation ? "Evidence review complete" : "Claims unverified"
      : workspace?.agentRun.status ?? "idle";
  const agentBadgeTone: Tone = workspace?.agentRun.status === "failed" ? "red" : workspace?.agentRun.status === "running" || investigationNeedsEvidence ? "yellow"
    : workspace?.agentRun.status === "complete" && workspace.agentRun.claimAudit?.status === "verified" && claimsCurrent ? "green" : "neutral";

  const applyHold = () => workspace && mutate("/api/actions/hold", { inputFingerprint: workspace.assessment.inputFingerprint, inventoryIds: confirmedIds, idempotencyKey: crypto.randomUUID() }, "Sandbox allocation hold recorded. Physical quarantine remains pending.");
  const reserve = () => feasible && mutate("/api/actions/reserve", { planFingerprint: feasible.planFingerprint, idempotencyKey: crypto.randomUUID() }, "Sandbox transfer reservations recorded. No dispatch or delivery is confirmed.");

  if (!workspace) return <div className="initial-screen"><Brand /><div className="initial-message" role={error ? "alert" : "status"}><span className="eyebrow">Recall response workspace</span><h1>{loading ? "Opening the workspace…" : "The workspace is unavailable"}</h1><p>{error ?? "Loading source evidence and the current incident."}</p>{!loading && <button onClick={() => { setLoading(true); setError(null); refresh().catch((cause: unknown) => setError(cause instanceof Error ? cause.message : "Could not load.")).finally(() => setLoading(false)); }}>Try again</button>}</div></div>;

  const physicalTotal = workspace.snapshot.inventory.reduce((sum, item) => sum + item.quantityEa, 0);
  const isReplay = workspace.dataMode === "replay" || workspace.snapshot.dataMode === "fixture";
  const inventoryNotAssessed = isInventoryUnassessed(workspace);
  const lotScope = presentLotScope(workspace.snapshot.scope.complete, workspace.recall.affectedLots.length);

  return <EvidenceProvider workspace={workspace}><div className="app-shell">
    <a href="#main-content" className="skip-link">Skip to workspace</a>
    <aside className="sidebar">
      <Brand />
      <div className="sidebar-caption">RECALL RESPONSE</div>
      <nav className="view-nav" aria-label="Workspace views">{views.map((item) => <button key={item.id} aria-current={view === item.id ? "page" : undefined} className={view === item.id ? "nav-item selected" : "nav-item"} onClick={() => setView(item.id)}><span className="nav-number">{item.number}</span>{item.label}{item.id === "actions" && workspace.receipts.length > 0 && <span className="nav-count">{workspace.receipts.length}</span>}</button>)}</nav>
      <div className="sidebar-incident"><span className="eyebrow">Current incident</span><span className="mono incident-id">{workspace.incidentId}</span><span className="quiet">Revision {workspace.revision}</span></div>
      <div className="sidebar-bottom"><div className="environment-line"><span className="status-dot" />{isReplay ? "Historical simulation" : "Live data mode"}</div><span className="quiet">Operational changes stay in the sandbox.</span><button className="secondary new-incident" disabled={busyOrRunning} onClick={() => { void mutate("/api/reset", {}, "A new incident is ready. The audit is preserved."); setView("recall"); }}>New incident<span aria-hidden="true">↗</span></button></div>
    </aside>

    <main id="main-content" className="main-content">
      <header className="workspace-header"><div><div className="breadcrumb">Workspace <span aria-hidden="true">/</span> {selected.label}</div><h1>{selected.title}</h1><p>{inventoryNotAssessed && view !== "recall" ? "Inventory assessment is unavailable for this investigation." : view === "recall" && !workspace.snapshot.scope.complete ? "Source evidence for human review; the full scope is not established." : selected.subtitle}</p></div><div className="header-meta"><Badge tone={isReplay ? "yellow" : "green"}>{isReplay ? "Historical replay" : "Live mode"}</Badge><Clock value={workspace.clock.analysisAt} date /><span className="quiet">{isReplay ? "Frozen at" : "Snapshot at"} <Clock value={workspace.clock.analysisAt} /></span><button className="secondary mobile-new-incident" disabled={busyOrRunning} onClick={() => { void mutate("/api/reset", {}, "A new incident is ready. The audit is preserved."); setView("recall"); }}>New incident</button></div></header>

      <div className="disclosure"><span className="disclosure-mark" aria-hidden="true">i</span><p>{workspace.disclosure}</p><details><summary>Replay details</summary><p>{isReplay ? "The recall identifiers are public facts. Sites, inventory, DEMO lots, release evidence, demand and logistics are fictional. Source material was retrieved after the replay date. Absence from this recall does not establish general product safety." : "Integration and source freshness are reported below. Check each source before approving an operational action."}</p></details></div>

      {error && <div className="feedback feedback-error" role="alert"><strong>Action needs attention</strong><span>{error}</span><button className="text-button" onClick={() => setError(null)} aria-label="Dismiss error">Dismiss</button></div>}
      {notice && <div className="feedback feedback-success" role="status"><span>{notice}</span><button className="text-button" onClick={() => setNotice(null)} aria-label="Dismiss notification">Dismiss</button></div>}

      {view === "recall" && <InvestigationGlance workspace={workspace} />}

      <section className="metrics" aria-label={inventoryNotAssessed ? "Inventory assessment" : "Inventory totals"}>{inventoryNotAssessed ? <p className="quiet" role="status">Inventory has not been assessed for this investigation.</p> : <><Metric label="Physical on hand" value={physicalTotal} detail="All stock, before inbound" /><Metric label="Available on hand" value={workspace.assessment.totalEligibleEa} detail="Usable, after holds and reservations" tone="green" /><Metric label="Recall affected" value={workspace.assessment.totalAffectedEa} detail="Blocked from use" tone="red" /><Metric label="Review / excluded" value={workspace.assessment.totalReviewOrExcludedEa} detail="Additional stock withheld" tone="yellow" /></>}</section>

      {isReplay && !workspace.evaluation?.caseId && <div className="scenario-bar"><div><span className="eyebrow">Demo scenario</span><span className="scenario-current">{scenarioLabels[workspace.scenario]}</span></div><div className="scenario-options" role="group" aria-label="Load a demo scenario">{(Object.keys(scenarioLabels) as Scenario[]).map((scenario) => <button key={scenario} className={scenario === workspace.scenario ? "scenario-option active" : "scenario-option"} aria-pressed={scenario === workspace.scenario} disabled={busyOrRunning || incidentReserved} onClick={() => { void mutate("/api/scenario", { scenario }, "Scenario loaded. Source versions and plan status refreshed."); }}>{scenarioLabels[scenario]}</button>)}</div></div>}

      {incidentReserved && <div className="feedback feedback-success" role="status"><span>Transfers are reserved for this incident. Start a new incident to explore another scenario or calculate a new plan; earlier receipts and the audit remain available.</span><button className="secondary" disabled={busyOrRunning} onClick={() => { void mutate("/api/reset", {}, "A new incident is ready. Earlier receipts and the audit are preserved."); setView("recall"); }}>New incident</button></div>}

      <div className="workspace-body"><div className="view-content" key={view}>
        {view === "recall" && <>
          <section className="panel recall-panel"><div className="section-heading"><span className="eyebrow">{workspace.evaluation?.caseId ? "Fictional case" : "Official recall"}</span><Badge tone={workspace.snapshot.scope.complete ? "red" : "yellow"}>{workspace.snapshot.scope.complete ? "Action required" : "Review required"}</Badge></div><h2>{workspace.recall.title}</h2><p className="mono source-reference"><EvidenceRef id={workspace.recall.reference} /></p><dl className="inline-facts"><div><dt>Manufacturer reference</dt><dd className="mono">{workspace.snapshot.scope.manufacturerRef}</dd></div><div><dt>Affected lot identifiers</dt><dd>{lotScope.count}</dd></div><div><dt>Allocation unit</dt><dd>{inventoryNotAssessed ? "Not assessed" : "One bottle · EA"}</dd></div></dl><div className="source-links">{workspace.recall.sources.map((source, index) => { const href = safeHttpUrl(source.url); return href ? <a key={source.id} href={href} target="_blank" rel="noopener noreferrer"><span className="source-index">{String(index + 1).padStart(2, "0")}</span><span>{source.title}</span><span aria-hidden="true">↗</span></a> : <div className="source-link-local" key={source.id}><span className="source-index">{String(index + 1).padStart(2, "0")}</span><EvidenceRef id={source.id} /><span className="quiet">Local evidence record</span></div>; })}</div>{lotScope.canInspect ? <details className="flat-details"><summary>{lotScope.heading}<span className="detail-count">{lotScope.countDetail}</span></summary><div className="lot-grid">{workspace.recall.affectedLots.map((lot) => <code key={lot}>{lot}</code>)}</div><p className="quiet">{lotScope.explanation}</p></details> : <p className="quiet">{lotScope.explanation}</p>}</section>
          {!workspace.evaluation?.caseId && <section className="panel conflict-panel"><div className="section-heading"><span className="eyebrow">Evidence conflict</span><Badge tone="yellow">Preserved for review</Badge></div><h3>One character changes the match.</h3><div className="conflict-pair"><div><span className="quiet">Distributor cover</span><code>{workspace.recall.conflict.observed}</code></div><span className="conflict-divider" aria-hidden="true">≠</span><div><span className="quiet">FDA + manufacturer scope</span><code>{workspace.recall.conflict.canonical}</code></div></div><p>{workspace.recall.conflict.explanation}</p><p className="quiet">Stock identifiers stay unchanged. A source conflict is investigated explicitly.</p></section>}
          <ResolutionMemoryPanel workspace={workspace} disabled={busyOrRunning} submit={(path,payload)=>mutate(path,payload,"Operator resolution memory updated. Inventory, QA and action authority are unchanged.")} />
          {!inventoryNotAssessed && <RecallTasks workspace={workspace} />}
        </>}

        {inventoryNotAssessed && view !== "recall" && <section className="panel" role="status"><h2>Inventory not assessed</h2><p>Exposure, response planning, and actions are unavailable until a current inventory source is read. Return to Recall to review the stored notices and checked record comparisons.</p></section>}

        {view === "exposure" && !inventoryNotAssessed && <>
          <section className="panel"><div className="section-heading"><div><span className="eyebrow">On-hand inventory</span><h2>Every lot has its own evidence.</h2></div><span className="mono quiet">{workspace.snapshot.inventory.length} rows</span></div><div className="table-scroll"><table className="inventory-table"><caption className="sr-only">Inventory, recall matches and separate local QA assessments</caption><thead><tr><th>Site / lot</th><th className="numeric">EA</th><th>Recall match</th><th>Local QA</th><th>Availability</th></tr></thead><tbody>{workspace.snapshot.inventory.map((item) => { const assessment = inventoryAssessments.get(item.id); return <React.Fragment key={item.id}><tr><td><strong>Site {item.siteId}</strong><code className="table-lot">{item.lot || "Lot missing"}</code>{item.allocationHold && <span className="hold-label">Sandbox hold applied</span>}</td><td className="numeric mono">{item.quantityEa}</td><td>{assessment ? <MatchBadge status={assessment.recallMatch.status} /> : "Unassessed"}</td><td><span className={`qa-label ${item.qaStatus === "UNVERIFIED" ? "qa-warning" : ""}`}>{item.qaStatus === "RELEASED" ? "Released" : item.qaStatus.replaceAll("_", " ").toLowerCase()}</span></td><td><Availability assessment={assessment} /></td></tr><tr className="row-detail"><td colSpan={5}><details><summary>Evidence &amp; checks<span className="mono"><EvidenceRef id={item.id} /></span></summary><div className="row-detail-content">{assessment && <Reasons reasons={assessment.reasons} />}<dl className="evidence-grid"><div><dt>QA evidence</dt><dd className="mono">{item.qaEvidenceRef ? <EvidenceRef id={item.qaEvidenceRef} /> : "Missing"}</dd></div><div><dt>Expiry evidence</dt><dd className="mono">{item.expiryEvidenceRef ? <EvidenceRef id={item.expiryEvidenceRef} /> : "Missing"}</dd></div><div><dt>Recorded expiry</dt><dd className="mono">{item.expiresAt ?? "Missing"}</dd></div><div><dt>Version / reserved</dt><dd className="mono">v{item.version} / {item.reservedEa} EA</dd></div></dl></div></details></td></tr></React.Fragment>; })}</tbody></table></div><div className="panel-footer"><p>{holdPending ? "Affected stock is excluded from planning. The digital hold has not yet been recorded." : "Confirmed affected rows have a recorded sandbox allocation hold."}</p><button disabled={busyOrRunning || incidentReserved || !holdPending || confirmedIds.length === 0} onClick={() => void applyHold()}>{busy === "/api/actions/hold" ? "Applying hold…" : "Apply sandbox hold"}</button></div><p className="fine-print">Digital holds do not confirm physical quarantine or destruction.</p></section>
          <section className="panel"><div className="section-heading"><div><span className="eyebrow">Expected supply</span><h3>Inbound is conditional.</h3></div><Badge tone="yellow">Source-reported status</Badge></div>{workspace.snapshot.shipments.map((shipment) => { const assessment = workspace.assessment.shipments.find((item) => item.entityId === shipment.id); return <div className="shipment-row" key={shipment.id}><div><strong>{shipment.quantityEa} EA → Site {shipment.destinationSiteId}</strong><span className="mono quiet"><EvidenceRef id={shipment.id} /></span><span className="quiet">{shipment.status === "RECEIVED" ? "Reported received" : shipment.status === "CANCELLED" ? "Cancelled" : "Projected · not received"}</span></div><div><span className="quiet">Expected arrival</span><Clock value={shipment.eta} /></div><Availability assessment={assessment} /></div>; })}<p className="fine-print">Projected availability depends on receipt and acceptance. Supply arriving after <Clock value={workspace.clock.cutoff} /> cannot cover this deadline.</p></section>
          <DemandTable workspace={workspace} />
        </>}

        {view === "plan" && !inventoryNotAssessed && <>
          <section className="panel plan-panel"><div className="section-heading"><div><span className="eyebrow">Checked allocation</span><h2>{workspace.planState === "stale" ? "The previous plan is stale." : workspace.planState === "reserved" ? "Transfers are reserved." : feasible ? "A feasible response." : plan ? "No feasible response." : "Calculate the response."}</h2></div><Badge tone={workspace.planState === "stale" ? "yellow" : feasible ? "green" : plan ? "red" : "neutral"}>{workspace.planState === "stale" ? "Recalculate" : workspace.planState === "reserved" ? "Sandbox reserved" : feasible ? "Feasible" : plan ? "Blocked" : "Not calculated"}</Badge></div><p className="quiet">Deterministic calculation · integer bottles · demand, reserves, capacity and arrival checks</p>{workspace.planState === "stale" && <div className="inline-warning" role="status">Relevant source data changed. This plan cannot be approved; calculate against the current snapshot.</div>}{!plan && <div className="empty-state"><span className="empty-symbol" aria-hidden="true">↗</span><p>Use the current evidence to find a feasible, lowest-cost transfer plan.</p><span className="quiet">No model call is required for this calculation.</span></div>}{feasible && <><div className="plan-totals"><div><span className="quiet">Transfer total</span><strong>{feasible.transfers.reduce((sum, transfer) => sum + transfer.quantityEa, 0)} <small>EA</small></strong></div><div><span className="quiet">Inbound counted</span><strong>{feasible.projectedInboundEa} <small>EA</small></strong></div><div><span className="quiet">Transport cost</span><strong>{feasible.transportCostPoints} <small>points</small></strong></div></div><div className="transfer-list">{feasible.transfers.length === 0 ? <p className="quiet">No inter-site transfer is required.</p> : feasible.transfers.map((transfer) => <div className="transfer-row" key={transfer.lineId}><div className="transfer-sites"><strong>Site {transfer.originSiteId}</strong><span className="transfer-arrow" aria-hidden="true">→</span><strong>Site {transfer.destinationSiteId}</strong></div><span className="transfer-quantity">{transfer.quantityEa}<small>EA</small></span><div className="transfer-time"><span className="quiet">Planned arrival</span><Clock value={transfer.arriveAt} /></div></div>)}</div><BalanceTable workspace={workspace} /><details className="flat-details"><summary>Validation &amp; plan evidence</summary><Reasons reasons={feasible.reasons} /><dl className="evidence-grid"><div><dt>Plan</dt><dd className="mono break-word">{feasible.id}</dd></div><div><dt>Valid until</dt><dd><Clock value={feasible.validUntil} /></dd></div><div className="wide"><dt>Input fingerprint</dt><dd className="mono break-word">{feasible.inputFingerprint}</dd></div><div className="wide"><dt>Plan fingerprint</dt><dd className="mono break-word">{feasible.planFingerprint}</dd></div></dl></details></>}{plan && plan.status !== "feasible" && <div className="rejected-plan"><div className="shortfall-number">{plan.shortfallEa}<small>EA shortfall</small></div><p>Required demand and reserves: <strong>{plan.totalRequiredEa} EA</strong>. Eligible supply considered: <strong>{plan.totalEligibleEa} EA</strong>{plan.projectedInboundEa > 0 ? ` plus ${plan.projectedInboundEa} EA projected inbound.` : "."}</p><Reasons reasons={plan.reasons} /><p className="fine-print">Execution approval is disabled. Investigate the missing supply or release evidence, then recalculate.</p></div>}<div className="panel-footer plan-buttons"><button className="secondary" disabled={busyOrRunning || incidentReserved} onClick={() => void mutate("/api/plan", {}, "Checked plan calculated from the current source versions.")}>{busy === "/api/plan" ? "Calculating…" : "Calculate checked plan"}</button><button disabled={busyOrRunning || !planCurrent || !feasible || !feasible.executionApprovalEnabled} onClick={() => void reserve()}>{busy === "/api/actions/reserve" ? "Reserving…" : "Reserve transfers in sandbox"}</button></div><p className="fine-print">Approval records sandbox lot reservations only. Dispatch, receipt and physical quarantine remain unconfirmed.</p></section>
          <WhatIfPanel key={`${workspace.incidentId}-${workspace.scenario}`} workspace={workspace} /><DemandTable workspace={workspace} /><section className="panel compact-panel"><div className="section-heading"><span className="eyebrow">Permitted transfer routes</span><span className="mono quiet">Dispatch by <Clock value={workspace.clock.dispatchAt} /></span></div><div className="route-list">{workspace.snapshot.routes.map((route) => <div key={route.id}><strong>{route.originSiteId} → {route.destinationSiteId}</strong><span className="route-evidence"><EvidenceRef id={route.id} /></span><span>{route.leadTimeMinutes} min</span><span>{route.costPointsPerEa} point{route.costPointsPerEa === 1 ? "" : "s"} / EA</span><span className="quiet">Capacity {route.capacityEa} EA</span></div>)}</div></section>
        </>}

        {view === "actions" && !inventoryNotAssessed && <>
          <section className="panel"><div className="section-heading"><div><span className="eyebrow">Sandbox action receipts</span><h2>Proposed is different from recorded.</h2></div><Badge>{workspace.receipts.length} receipts</Badge></div><div className="action-control-row"><div><strong>Allocation hold</strong><p className="quiet">Record a digital hold on confirmed affected inventory.</p></div><button disabled={busyOrRunning || incidentReserved || !holdPending || confirmedIds.length === 0} onClick={() => void applyHold()}>Apply sandbox hold</button></div><div className="action-control-row"><div><strong>Transfer reservations</strong><p className="quiet">Requires a current, feasible checked plan.</p></div><button disabled={busyOrRunning || !planCurrent || !feasible || !feasible.executionApprovalEnabled} onClick={() => void reserve()}>Reserve transfers in sandbox</button></div>{workspace.receipts.length === 0 ? <div className="empty-state compact"><p>No sandbox actions have been recorded.</p><span className="quiet">A recommendation or draft does not establish an action.</span></div> : <div className="receipt-list">{[...workspace.receipts].reverse().map((receipt) => <article className="receipt" key={receipt.id}><div className="receipt-top"><Badge tone="green">{receipt.action === "hold" ? "Hold recorded" : "Reservation recorded"}</Badge><Clock value={receipt.at} /></div><p>{receipt.semantic}</p><details className="flat-details"><summary>Receipt details</summary><dl className="evidence-grid"><div><dt>Receipt</dt><dd className="mono break-word">{receipt.id}</dd></div><div><dt>Incident</dt><dd className="mono break-word">{receipt.incidentId}</dd></div><div className="wide"><dt>Input fingerprint</dt><dd className="mono break-word">{receipt.inputFingerprint}</dd></div><div className="wide"><dt>Idempotency key</dt><dd className="mono break-word">{receipt.idempotencyKey}</dd></div></dl>{receipt.inventoryIds.length > 0 && <p className="mono quiet break-word">{receipt.inventoryIds.join(", ")}</p>}{receipt.transfers.map((transfer) => <p key={transfer.lineId}>Site {transfer.originSiteId} → Site {transfer.destinationSiteId}: {transfer.quantityEa} EA</p>)}</details></article>)}</div>}<p className="fine-print">No physical quarantine, destruction, dispatch, delivery, submitted response or received credit is claimed.</p></section>
          {!inventoryNotAssessed && <RecallTasks workspace={workspace} />}<section className="panel"><div className="section-heading"><div><span className="eyebrow">Incident history</span><h3>Audit trail</h3></div><span className="mono quiet">{workspace.audit.length} events</span></div>{workspace.audit.length === 0 ? <p className="quiet">No audit events recorded.</p> : <ol className="audit-list">{[...workspace.audit].reverse().map((event) => <li key={event.id}><div><Clock value={event.at} /><span className="mono audit-type">{event.type.replaceAll("_", " ")}</span></div><p>{event.message}</p></li>)}</ol>}<p className="fine-print">Starting a new incident preserves the server audit.</p></section>
        </>}
      </div>

      <aside className="context-rail" aria-label="Agent and source context"><section className="panel agent-panel"><div className="section-heading"><span className="eyebrow">Agent investigation</span><Badge tone={agentBadgeTone}>{agentBadge}</Badge></div><h3>Follow the evidence.</h3><p className="quiet">The AI agent reads the recall notices and stock data, then writes a report. Engram checks every quote and number before it is shown. A person still approves any action.</p>{workspace.agentRun.model || workspace.agent.model ? <p className="model-name mono">{workspace.agentRun.model ?? workspace.agent.model}</p> : null}{!workspace.agent.enabled && <div className="agent-gate"><span className="status-dot muted" /><p>{workspace.agent.reason || "Agent access is unavailable. Check the integration details."}</p></div>}<form onSubmit={(event) => { event.preventDefault(); void mutate("/api/analyze", agentMessage.trim() ? { message: agentMessage.trim() } : {}, "Investigation requested. The panel reports actual tool activity."); }}><label htmlFor="agent-message" className="sr-only">Optional investigation question</label><textarea id="agent-message" value={agentMessage} onChange={(event) => setAgentMessage(event.target.value)} placeholder="Optional: ask about exposure, evidence or the response…" rows={3} disabled={busyOrRunning || !workspace.agent.enabled} /><button className="agent-button" type="submit" disabled={busyOrRunning || !workspace.agent.enabled}>{workspace.agentRun.status === "running" ? "Investigating…" : busy === "/api/workspace" ? "Refreshing sources…" : busy === "/api/analyze" ? "Starting…" : "Investigate evidence"}<span aria-hidden="true">↗</span></button></form>{workspace.agentRun.status === "running" && <div className="agent-recovery"><button className="secondary" disabled={!!busy || !workspace.agentRun.runId} onClick={() => void mutate("/api/cancel", { runId: workspace.agentRun.runId }, "Investigation stopped. You can start a new investigation or reset the incident.")}>{busy === "/api/cancel" ? "Stopping…" : "Stop investigation"}</button><p className="fine-print">Recover an interrupted run before starting a new incident.</p></div>}<details className="flat-details activity-details" open><summary>What the agent actually did<span className="detail-count">{workspace.agentRun.events.length} logged</span></summary><ToolTimeline events={workspace.agentRun.events} model={workspace.agentRun.model ?? workspace.agent.model} /></details>{workspace.agentRun.summary && (!workspace.agentRun.investigation || workspace.agentRun.investigation.disposition !== null) && <div className="agent-summary"><span className="eyebrow">{inventoryNotAssessed ? "Operational inventory not assessed" : workspace.assessment.valid ? "Checked exposure · current snapshot" : "Exposure assessment · invalid inputs"}</span>{inventoryNotAssessed ? <p className="quiet">Inventory exposure totals are unavailable for this investigation.</p> : <><p><strong>{workspace.assessment.totalAffectedEa} EA recall affected · excluded</strong><br />{workspace.assessment.totalEligibleEa} EA eligible and unreserved<br />{workspace.assessment.totalReviewOrExcludedEa} EA additional review / excluded</p><p className="quiet">Affected stock is excluded from allocation. Prior QA release cannot override a recall match. Approval controls use the checked plan.</p></>}<details className="flat-details"><summary>{workspace.agentRun.claimAudit?.status === "verified" ? "Checked claims · investigation snapshot" : workspace.agentRun.investigation ? "Evidence investigation · model interpretation" : "Model claims · unverified"}</summary><p>{workspace.agentRun.summary}</p>{workspace.agentRun.claimAudit?.status === "verified" && <ul className="reason-list">{workspace.agentRun.claimAudit.result.checked?.explanations.map((explanation, index) => <li key={index}>{explanation.text}<details><summary>Source references</summary><p className="mono break-word">{explanation.citations.map((citation) => <EvidenceRef key={citation} id={citation} scope="bound" claim={explanation.text} />)}</p></details></li>)}</ul>}<p className="fine-print">Checks apply to the captured investigation snapshot. {claimsCurrent ? "Its hash matches this displayed assessment." : "Recalculate or investigate again if current source values changed."} Approval rereads current sources.</p></details></div>}{workspace.agentRun.investigation && <InvestigationFindings workspace={workspace} />}{workspace.agentRun.claimAudit && (!workspace.agentRun.investigation || workspace.agentRun.investigation.disposition !== null) && <details className="flat-details"><summary>Raw model output · audit only</summary>{workspace.agentRun.claimAudit.rawAttempts.map((raw, index) => <pre className="mono break-word" key={index} style={{whiteSpace: "pre-wrap"}}>{raw}</pre>)}</details>}{workspace.agentRun.error && <p className="agent-error" role="alert">{workspace.agentRun.error}</p>}<p className="fine-print">The checked allocation calculation is separate from model reasoning.</p></section>
      <section className="panel integrations-panel"><span className="eyebrow">Connected systems</span><Integration name="Zetaris" status={workspace.integrations.zetaris} /><Integration name="Meterless" status={workspace.integrations.meterless} /><details className="flat-details"><summary>Snapshot details</summary>{workspace.snapshot.sourceRead && <p className="quiet">Investigation source capture: {workspace.snapshot.sourceRead.retrievedAt}. {workspace.snapshot.sourceRead.queryCount} queries, {workspace.snapshot.sourceRead.elapsedMs} ms source collection.</p>}{workspace.snapshot.recallProvenance && <p className="quiet">Reviewed FDA snapshot retrieved {workspace.snapshot.recallProvenance.retrievedAt}; dataset updated {workspace.snapshot.recallProvenance.datasetLastUpdated}. Historical operations replay: 2 May 2025. FDA scope via Zetaris: {workspace.snapshot.recallProvenance.zetarisScopeRead ? "read and matched" : "not read through Zetaris"}.</p>}<dl className="evidence-grid"><div className="wide"><dt>Data mode</dt><dd>{workspace.dataMode} / {workspace.snapshot.dataMode}</dd></div><div className="wide"><dt>Input fingerprint</dt><dd className="mono break-word">{workspace.assessment.inputFingerprint}</dd></div></dl><ul className="source-versions">{Object.entries(workspace.snapshot.sourceVersions).map(([source, version]) => <li key={source}><span className="mono break-word">{source}</span><span className="mono">v{version}</span></li>)}</ul>{!workspace.assessment.valid && !inventoryNotAssessed && <Reasons reasons={workspace.assessment.reasons} />}</details></section>
      {!inventoryNotAssessed && <div className="rail-note"><span className="eyebrow">Coverage deadline</span><strong><Clock value={workspace.clock.cutoff} /></strong><p>Keep demand and ending reserves covered at every site.</p></div>}</aside></div>
      <footer className="workspace-footer"><span>Engram <span aria-hidden="true">/</span> Evidence → checked response</span><span>{inventoryNotAssessed ? "Inventory quantities not assessed" : "Quantities in individual bottles · EA"}</span></footer>
    </main>
  </div></EvidenceProvider>;
}

function Brand() {
  return <div className="brand"><span>Engram<span className="brand-period">.</span></span></div>;
}
function Metric({ label, value, detail, tone = "neutral" }: { label: string; value: number; detail: string; tone?: Tone }) {
  return <div className={`metric metric-${tone}`}><span className="metric-label">{label}</span><div className="metric-value">{value}<small>EA</small></div><span className="metric-detail">{detail}</span></div>;
}
function DemandTable({ workspace }: { workspace: Workspace }) {
  return <section className="panel compact-panel"><div className="section-heading"><div><span className="eyebrow">Coverage requirements</span><h3>Demand + ending reserves</h3></div><Clock value={workspace.clock.cutoff} /></div><div className="table-scroll"><table><caption className="sr-only">Site demand and required ending reserve in bottles</caption><thead><tr><th>Site</th><th className="numeric">Demand</th><th className="numeric">Ending reserve</th><th className="numeric">Required</th></tr></thead><tbody>{workspace.snapshot.demands.map((demand) => <tr key={demand.id}><td><strong>Site {demand.siteId}</strong><span className="demand-row-id"><EvidenceRef id={demand.id} /></span></td><td className="numeric mono">{demand.demandEa}</td><td className="numeric mono">{demand.requiredReserveEa}</td><td className="numeric mono">{demand.demandEa + demand.requiredReserveEa} EA</td></tr>)}</tbody></table></div><p className="fine-print">Reserves are required ending stock after demand, rather than existing reservations.</p></section>;
}
function BalanceTable({ workspace }: { workspace: Workspace }) {
  const plan = workspace.plan;
  if (plan?.status !== "feasible") return null;
  return <div className="balance-section"><span className="eyebrow">Projected balances after demand</span><div className="table-scroll"><table><caption className="sr-only">Checked projected balances for each site</caption><thead><tr><th>Site</th><th className="numeric">On hand</th><th className="numeric">Inbound</th><th className="numeric">Net transfer</th><th className="numeric">Demand</th><th className="numeric">Ending / reserve</th></tr></thead><tbody>{plan.siteBalances.map((balance) => <tr key={balance.siteId}><td><strong>{balance.siteId}</strong></td><td className="numeric mono">{balance.eligibleOnHandEa}</td><td className="numeric mono">{balance.projectedInboundEa}</td><td className="numeric mono">{balance.incomingTransferEa - balance.outgoingTransferEa > 0 ? "+" : ""}{balance.incomingTransferEa - balance.outgoingTransferEa}</td><td className="numeric mono">−{balance.demandEa}</td><td className="numeric mono"><span className="positive">{balance.projectedEndEa}</span><span className="quiet"> / {balance.requiredReserveEa}</span></td></tr>)}</tbody></table></div></div>;
}
function RecallTasks({ workspace }: { workspace: Workspace }) {
  return <section className="panel tasks-panel"><div className="section-heading"><div><span className="eyebrow">Required follow-up</span><h3>Keep the recall obligations visible.</h3></div></div><ul className="task-list">{workspace.recall.tasks.map((task, index) => <li key={task.id}><span className="task-number mono">{String(index + 1).padStart(2, "0")}</span><strong>{task.title}</strong><Badge tone="yellow">{task.status.replaceAll("_", " ").toLowerCase()}</Badge></li>)}</ul><p className="fine-print">These sourced tasks remain pending until their real-world completion is independently recorded.</p></section>;
}
function Integration({ name, status }: { name: string; status: IntegrationStatus }) {
  return <details className="integration"><summary><span className={`status-dot ${status.verified ? "verified" : "muted"}`} /><strong>{name}</strong><span className="integration-status">{status.status}</span></summary><p>{status.detail}</p><span className="quiet">Configured: {status.configured ? "yes" : "no"} · Verified: {status.verified ? "yes" : "no"}</span></details>;
}

function InvestigationFindings({ workspace }: { workspace: Workspace }) {
  const investigation = workspace.agentRun.investigation;
  if (!investigation) return null;
  const needsEvidence = investigation.disposition === "needs_evidence" || workspace.agentRun.status === "blocked";
  const partial = isPartialInvestigation(workspace);
  const partialEvidence = boundPartialEvidence(workspace);
  const recordChecks = partial ? partialEvidence.recordChecks : (investigation.recordMatches ?? []);
  return <section className="investigation-findings" aria-label="Evidence investigation findings">
    <div className="investigation-findings-heading"><span className="eyebrow">{investigationHeading(workspace)}</span><span className="quiet">{investigation.findings.length} finding{investigation.findings.length === 1 ? "" : "s"}</span></div>
    {partial && <div role="status"><p><strong>Incomplete investigation · human review required.</strong> No report was accepted. These source snapshots and field comparisons are partial evidence, not a recall determination or instruction to act. Read the full notices and independently assess scope, conditions and actions.</p>{partialEvidence.notices.length > 0 ? <div className="partial-source-list"><p>Inspected notice snapshots, bound to this run:</p>{partialEvidence.notices.map(entry => <article key={`${entry.id}-${entry.sourceHash}`}><p><strong>{entry.title}</strong> · {entry.authority.replaceAll("-", " ")} · <EvidenceRef id={entry.id} sourceHash={entry.sourceHash} scope="bound" /></p><details className="flat-details"><summary>Read full stored source text</summary><pre className="evidence-content">{entry.content}</pre></details></article>)}</div> : <p>No bound notice snapshot is available in this partial view.</p>}<p className="fine-print">The source text is the stored snapshot, which may be an excerpt rather than the full original document. Inspection does not establish completeness, currency or applicability.</p></div>}
    {investigation.disposition !== null && <p className="investigation-summary">{investigation.summary}</p>}
    {investigation.disposition !== null && !!investigation.withheldFindings?.length && <div className="operator-question" role="status"><span className="eyebrow">Partially verified · human review required</span><p>The final draft had {investigation.withheldFindings.length} finding{investigation.withheldFindings.length === 1 ? "" : "s"} that failed validation. {investigation.withheldFindings.length === 1 ? "It was" : "They were"} withheld; everything shown below passed the full check again without {investigation.withheldFindings.length === 1 ? "it" : "them"}.</p><ul className="reason-list">{investigation.withheldFindings.map((finding, index) => <li key={index}><span>Withheld {finding.kind.replaceAll("_", " ")}: <code className="break-word">{finding.codes.map(code => code.replaceAll("_", " ")).join("; ")}</code></span><details><summary>Show withheld text (failed validation, not accepted)</summary><p className="quiet">{finding.summary}</p></details></li>)}</ul></div>}
    {needsEvidence && investigation.disposition !== null && <div className="operator-question" role="status"><span className="eyebrow">Operator question</span><p>{investigation.question ?? "The investigation needs more source evidence before it can continue."}</p></div>}
    {!!recordChecks.length && <details className="flat-details" open={partial || undefined}><summary>Show exact record-check receipts ({recordChecks.length})</summary><p className="fine-print">Backend comparisons of explicit source fields, attached separately from the written findings. They do not establish recall applicability, clearance or completed physical actions.</p><div className="table-scroll"><table><caption className="sr-only">Stored source-bound record comparisons</caption><thead><tr><th>Record</th><th>Notice</th><th>Field</th><th>Recorded value</th><th>Result</th><th>Reason and source excerpts</th></tr></thead><tbody>{recordChecks.map(result => <tr key={result.resultId}><td>{result.recordId}</td><td>{[...new Map(result.evidence.filter(proof => workspace.investigationEvidence?.entries.some(entry => entry.id === proof.sourceId && entry.kind === "notice")).map(proof => [proof.sourceId, proof])).values()].map(proof => <EvidenceRef key={proof.sourceId} id={proof.sourceId} sourceHash={proof.sourceHash} scope="bound" />)}</td><td>{result.field.replaceAll("_", " ")}</td><td className="mono break-word">{result.normalizedRecordValue ?? "unknown"}</td><td>{result.status.replaceAll("_", " ")}</td><td>{result.reason.replaceAll("_", " ")}{partial && <details><summary>View exact comparison excerpts</summary>{result.evidence.map((proof, index) => <EvidenceCitation key={`${proof.sourceId}-${index}`} id={proof.sourceId} sourceHash={proof.sourceHash} quote={proof.quote} claim="Source excerpt used in this field comparison" />)}</details>}</td></tr>)}</tbody></table></div></details>}
    {investigation.disposition !== null && <ul className="finding-list">{investigation.findings.map((finding) => <li key={finding.id}><span className="finding-kind">{finding.kind.replaceAll("_", " ")}</span><strong>{finding.summary}</strong><p className="fine-print">{finding.origin === "backend_record_check" ? "Backend record check · rendered from stored field comparisons, not written by the model · not a recall determination" : finding.recordChecks?.length ? "Documentary quotes and complete checked receipts selected by Nemotron · interpretation requires review" : "Notice interpretation by Nemotron · quotes verified verbatim, wording requires human review"}</p>{finding.question && <div className="operator-question" role="status"><span className="eyebrow">Follow-up question</span><p>{finding.question}</p></div>}<div className="finding-quotes">{finding.evidence.map((citation, index) => <EvidenceCitation key={`${finding.id}-${citation.sourceId}-${index}`} id={citation.sourceId} sourceHash={citation.sourceHash} quote={citation.quote} claim={finding.summary} />)}</div></li>)}</ul>}
  </section>;
}

function ResolutionMemoryPanel({workspace,disabled,submit}:{workspace:Workspace;disabled:boolean;submit:(path:string,payload:unknown)=>Promise<void>}) {
  const [operator,setOperator]=useState("");const [reason,setReason]=useState("");const [confirmed,setConfirmed]=useState(false);
  const [expiry,setExpiry]=useState(()=>new Date(Date.now()+30*86400000).toISOString().slice(0,10));const [revokeReason,setRevokeReason]=useState("");
  const memory=workspace.resolutionMemory;
  if(!memory) return null;
  return <section className="panel"><div className="section-heading"><div><span className="eyebrow">Operator memory</span><h3>Resolve the document question once.</h3></div><Badge tone={memory.decisions.some(d=>d.status==="applied")?"green":"yellow"}>{memory.decisions.some(d=>d.status==="applied")?"Resolution consulted":"Source review needed"}</Badge></div><p className="quiet">{memory.nextInvestigationQuestion}</p><p className="fine-print">This records a human review of 23IJA103 / 23JJA103 in the source documents. It cannot change physical stock identifiers, recall matching, QA release, stock availability or approval controls.</p>{memory.decisions.map(decision=><article className="receipt" key={decision.memoryId}><Badge tone={decision.status==="applied"?"green":"yellow"}>{decision.status}</Badge><p>{decision.reason}</p><p className="quiet">{decision.operator} · expires {decision.expiresAt}{decision.reasonCodes.length?` · ${decision.reasonCodes.join(", ")}`:""}</p>{decision.status==="applied"&&<><label>Reason to revoke<input value={revokeReason} onChange={e=>setRevokeReason(e.target.value)} maxLength={1000} disabled={disabled}/></label><button className="secondary" disabled={disabled||!revokeReason.trim()} onClick={()=>void submit("/api/memory/revoke",{memoryId:decision.memoryId,reason:revokeReason.trim()})}>Revoke resolution</button></>}</article>)}<details className="flat-details"><summary>Record a source-backed operator resolution</summary><form onSubmit={event=>{event.preventDefault();void submit("/api/memory/resolution",{sourceHash:memory.sourceHash,operator:operator.trim(),reason:reason.trim(),expiresAt:`${expiry}T23:59:59.000Z`,sourceReviewConfirmed:confirmed});}}><label>Operator name<input required value={operator} onChange={e=>setOperator(e.target.value)} maxLength={120} disabled={disabled}/></label><label>Evidence and resolution<textarea required value={reason} onChange={e=>setReason(e.target.value)} maxLength={1000} rows={3} placeholder="Explain the document discrepancy and the source evidence you reviewed." disabled={disabled}/></label><label>Expires on<input required type="date" value={expiry} onChange={e=>setExpiry(e.target.value)} disabled={disabled}/></label><label><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)} disabled={disabled}/> I reviewed the current FDA and manufacturer lot-scope sources.</label><button type="submit" disabled={disabled||!confirmed||!operator.trim()||!reason.trim()||!expiry}>Save document resolution</button></form><p className="mono break-word quiet">Source binding: {memory.sourceHash}</p><p className="mono break-word quiet">{memory.sourceRefs.map((ref) => <EvidenceRef key={ref} id={ref} />)}</p></details></section>;
}
